// ---- context: what every procedure can access ----
import { initTRPC, TRPCError } from '@trpc/server';
import superjson from 'superjson';               // Date, Map, Set, BigInt over JSON

export interface Context {
  db: Database;
  user: AuthUser | null;
  tenantId: string;
  req: Request;                                  // for headers/cookies
}
export async function createContext({ req }: { req: Request }): Promise<Context> {
  const user = await authenticate(req);
  return { db: dbFor(user?.tenantId ?? 'public'), user, tenantId: user?.tenantId ?? 'public', req };
}
const t = initTRPC.context<Context>().create({ transformer: superjson, errorFormatter: toProblemDetails });

// ---- reusable building blocks ----
const timing = t.middleware(async ({ next, path }) => {
  const start = performance.now();
  const result = await next();
  console.log(`${path} took ${Math.round(performance.now() - start)}ms`);
  return result;
});
const authed = t.middleware(({ ctx, next }) => {
  if (!ctx.user) throw new TRPCError({ code: 'UNAUTHORIZED', message: 'Sign in required' });
  return next({ ctx: { ...ctx, user: ctx.user } });   // narrow the type for downstream procedures
});
const rateLimit = t.middleware(async ({ ctx, next, path }) => {
  const { allowed, remaining, resetMs } = await limiter.check(ctx.user?.id ?? ctx.req.ip, path);
  if (!allowed) throw new TRPCError({ code: 'TOO_MANY_REQUESTS', message: 'Slow down' });
  return next({ ctx: { ...ctx, limits: { remaining, resetMs } } });
});
const publicProcedure = t.procedure.use(timing).use(rateLimit);
const protectedProcedure = publicProcedure.use(authed);
